677	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
678	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
679		state, err := s.readState()
680		if err != nil {
681			return ProposalRecord{}, false, err
682		}
683		p, ok := state.Proposals[id]
684		if !ok {
685			return ProposalRecord{}, false, nil
686		}
687		return toProposalRecord(p), true, nil
688	}
