690	// Proposals 返回全部已登记提案，按编号排序。
691	func (s *Store) Proposals() ([]ProposalRecord, error) {
692		state, err := s.readState()
693		if err != nil {
694			return nil, err
695		}
696		return proposalRecords(state), nil
697	}
