699	func proposalRecords(state *storedState) []ProposalRecord {
700		out := make([]ProposalRecord, 0, len(state.Proposals))
701		for _, p := range state.Proposals {
702			out = append(out, toProposalRecord(p))
703		}
704		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
705		return out
706	}
