708	// ProposalsSnapshot 是同一份完整已提交状态下的登记提案与投票提案列表。
709	// 一次 ProposalsSnapshot 调用只读取一次状态文件，保证两个来源的提案状态、
710	// 动作与投票明细彼此一致：不会把不同提交时刻的提案状态拼在一起。
711	type ProposalsSnapshot struct {
712		Registered []ProposalRecord    `json:"registered"`
713		Voting     []*VoteProposalView `json:"voting"`
714	}
