716	// ProposalsSnapshot 在一次持锁读取中取得全部登记提案与全部投票提案。
717	// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
718	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
719	func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
720		state, err := s.readState()
721		if err != nil {
722			return nil, err
723		}
724		return &ProposalsSnapshot{
725			Registered: proposalRecords(state),
726			Voting:     voteProposalViews(state),
727		}, nil
728	}
