1139	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1140	
1141	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1142	type schemaKind int
1143	
1144	const (
1145		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1146		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1147		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1148		kindArray                     // 数组
1149		kindString                    // 叶子：必须是 JSON 字符串
1150		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1151		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1152	)
1153	
1154	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1155	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1156	type schemaNode struct {
1157		kind   schemaKind
1158		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1159		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1160	}
1161	
1162	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1163	func schemaOf(t reflect.Type) *schemaNode {
1164		for t.Kind() == reflect.Pointer {
1165			t = t.Elem()
1166		}
1167		switch t.Kind() {
1168		case reflect.Struct:
1169			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1170			for i := 0; i < t.NumField(); i++ {
1171				f := t.Field(i)
1172				if f.PkgPath != "" { // 未导出字段不参与 JSON
1173					continue
1174				}
1175				name := f.Name
1176				if tag, ok := f.Tag.Lookup("json"); ok {
1177					tagName, _, _ := strings.Cut(tag, ",")
1178					if tagName == "-" {
1179						continue
1180					}
1181					if tagName != "" {
1182						name = tagName
1183					}
1184				}
1185				node.fields[name] = schemaOf(f.Type)
1186			}
1187			return node
1188		case reflect.Map:
1189			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1190		case reflect.Slice, reflect.Array:
1191			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1192		case reflect.String:
1193			return &schemaNode{kind: kindString}
1194		case reflect.Bool:
1195			return &schemaNode{kind: kindBoolean}
1196		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1197			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1198			return &schemaNode{kind: kindInteger}
1199		default:
1200			return &schemaNode{kind: kindAny}
1201		}
1202	}
1203	
1204	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1205	
1206	func init() {
1207		// 票据的四个标量字段（representative/weight/support/voted_at）由
1208		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1209		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1210		// 不抢在解码器之前用不含票据定位的通用信息报错。
1211		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1212		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1213			ballotFields[name].kind = kindAny
1214		}
1215		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1216		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1217		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1218		// 其“不早于截止”的既有校验不变。
1219		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1220		for _, name := range []string{"for_weight", "against_weight"} {
1221			tallyFields[name].kind = kindAny
1222		}
1223		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1224		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1225		// 叶子位置保持宽松。
1226		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1227		receiptFields["executed_at"].kind = kindAny
1228		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1229		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1230		receiptFields["order"].kind = kindAny
1231		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1232		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1233		// 此叶子位置保持宽松。
1234		receiptFields["actions"].elem.fields["index"].kind = kindAny
1235		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1236		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1237		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1238		actionFields := receiptFields["actions"].elem.fields
1239		for _, side := range []string{"treasury", "recipient"} {
1240			balanceFields := actionFields[side].fields
1241			balanceFields["before"].kind = kindAny
1242			balanceFields["after"].kind = kindAny
1243		}
1244	}
