528		}
529		fmt.Printf("treasury %d\n", snapshot.Treasury)
530		accounts := make([]string, 0, len(snapshot.Balances))
531		for acct := range snapshot.Balances {
532			accounts = append(accounts, acct)
533		}
534		sort.Strings(accounts)
