1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"math"
7		"os"
8		"path/filepath"
9		"strings"
10		"sync"
11		"testing"
12		"time"
13	)
14	
15	func openTempStore(t *testing.T, balance int64) (*Store, string) {
16		t.Helper()
17		path := filepath.Join(t.TempDir(), "treasury.json")
18		store, err := InitTreasury(path, balance)
19		if err != nil {
20			t.Fatalf("InitTreasury: %v", err)
21		}
22		return store, path
23	}
24	
25	func mustRegister(t *testing.T, store *Store, id string, timelock int64, actions ...string) {
26		t.Helper()
27		if existed, err := store.Register(id, timelock, actions); err != nil || existed {
28			t.Fatalf("Register(%s) existed=%v err=%v", id, existed, err)
29		}
30	}
31	
32	func TestInitOnlyNewFile(t *testing.T) {
33		path := filepath.Join(t.TempDir(), "treasury.json")
34		store, err := InitTreasury(path, 1000)
35		if err != nil {
36			t.Fatalf("InitTreasury: %v", err)
37		}
38		store.Close()
39	
40		if _, err := InitTreasury(path, 9999); !errors.Is(err, ErrTreasuryAlreadyInit) {
41			t.Fatalf("second init err=%v, want ErrTreasuryAlreadyInit", err)
42		}
43		// 已有文件不得重置余额。
44		reopened, err := Open(path)
45		if err != nil {
46			t.Fatalf("Open: %v", err)
47		}
48		defer reopened.Close()
49		if bal, _ := reopened.TreasuryBalance(); bal != 1000 {
50			t.Fatalf("treasury was reset: %d", bal)
51		}
52	
53		// 初始化负数余额被拒绝。
54		if _, err := InitTreasury(filepath.Join(t.TempDir(), "x.json"), -1); !errors.Is(err, ErrInvalidRegistration) {
55			t.Fatalf("negative init err=%v", err)
56		}
57	}
58	
59	func TestRegisterIdempotentAndConflict(t *testing.T) {
60		store, _ := openTempStore(t, 1000)
61		defer store.Close()
62	
63		if _, err := store.Register("", 10, []string{"transfer:a:1"}); !errors.Is(err, ErrInvalidRegistration) {
64			t.Fatalf("empty id err=%v", err)
65		}
66	
67		mustRegister(t, store, "gip-1", 100, "transfer:audits:25000", "transfer:legal:5")
68	
69		// 完全相同的重试：返回 existed，不新增记录。
70		existed, err := store.Register("gip-1", 100, []string{"transfer:audits:25000", "transfer:legal:5"})
71		if err != nil || !existed {
72			t.Fatalf("identical retry existed=%v err=%v", existed, err)
73		}
74		// nil 与空切片等价。
75		existed, err = store.Register("gip-empty", 0, nil)
76		if err != nil || existed {
77			t.Fatalf("register empty actions: %v %v", existed, err)
78		}
79		existed, err = store.Register("gip-empty", 0, []string{})
80		if err != nil || !existed {
81			t.Fatalf("empty actions retry: %v %v", existed, err)
82		}
83	
84		// 时间锁不同。
85		if _, err := store.Register("gip-1", 101, []string{"transfer:audits:25000", "transfer:legal:5"}); !errors.Is(err, ErrProposalConflict) {
86			t.Fatalf("timelock conflict err=%v", err)
87		}
88		// 动作原文不同（含顺序不同）。
89		if _, err := store.Register("gip-1", 100, []string{"transfer:legal:5", "transfer:audits:25000"}); !errors.Is(err, ErrProposalConflict) {
90			t.Fatalf("action order conflict err=%v", err)
91		}
92		if _, err := store.Register("gip-1", 100, []string{"transfer:audits:25000"}); !errors.Is(err, ErrProposalConflict) {
93			t.Fatalf("action count conflict err=%v", err)
94		}
95	
96		records, err := store.Proposals()
97		if err != nil || len(records) != 2 {
98			t.Fatalf("Proposals len=%d err=%v", len(records), err)
99		}
100		if records[0].ID != "gip-1" || records[0].State != "passed" {
