720					}
721					if so != "" {
722						t.Fatalf("%v stdout must stay empty on corruption, got %q", args, so)
723					}
724					for _, want := range tc.wantMsg {
725						if !strings.Contains(se, want) {
726							t.Fatalf("%v stderr %q missing %q", args, se, want)
727						}
728					}
729				}
730				// 不整理、补齐或覆盖缺损文件。
731				if got, err := os.ReadFile(bad); err != nil || string(got) != corrupt {
732					t.Fatalf("corrupt file was modified or rewritten")
733				}
734			})
735		}
