// TestNoPartialReadsDuringWrite 通过检查文件始终是合法 JSON 来观察原子性。
func TestAtomicFileIsAlwaysValid(t *testing.T) {
	path := filepath.Join(t.TempDir(), "treasury.json")
	store, err := InitTreasury(path, 100000)
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
